passages:
{"acquirer": [{"quote": "On January 11, 2026, D. Boral ARC Acquisition I Corp.
(“BCAR” or the “Company”) entered into the Agreement and Plan of Merger (the “Merger Agreement”) by
and among BCAR, D. Boral ARC Merger Corporation, a Delaware corporation and wholly owned subsidiary of BCAR (“PubCo”), D.
Boral Arc Merger Sub Inc. (“Merger Sub”), a Delaware corporation and a wholly-owned subsidiary of BCAR, and Exascale Labs
Inc.., a Delaware corporation (“Exascale”).", "location": "FORM 8-K, Item 1.01. Entry Into a Material Definitive Agreement", "relevance_score": 5}, {"quote": "At the Reincorporation Effective Time, subject to and upon the terms and conditions of this Agreement and in accordance with the applicable provisions of the BVI BCA and the DGCL, Parent shall be merged with and into Purchaser, the separate corporate existence of Parent shall cease and Purchaser shall continue as the surviving company.", "location": "EX-2.1, Section 2.1 Reincorporation", "relevance_score": 5}, {"quote": "Upon the terms and subject to the conditions set forth in this Agreement and the Organizational Documents of Merger Sub and in accordance with the DGCL, at the Effective Time, (a) Merger Sub shall be merged with and into the Company, (b) the separate corporate existence of Merger Sub shall thereupon cease, (c) the Company shall be the surviving company in the Merger (“Company Surviving Corporation”) and (d) the Company shall become a wholly-owned Subsidiary of Purchaser Surviving Corporation.", "location": "EX-2.1, Section 3.1 The Merger", "relevance_score": 5}], "target": [{"quote": "On January 11, 2026, D. Boral ARC Acquisition I Corp.
(“BCAR” or the “Company”) entered into the Agreement and Plan of Merger (the “Merger Agreement”) by
and among BCAR, D. Boral ARC Merger Corporation, a Delaware corporation and wholly owned subsidiary of BCAR (“PubCo”), D.
Boral Arc Merger Sub Inc. (“Merger Sub”), a Delaware corporation and a wholly-owned subsidiary of BCAR, and Exascale Labs
Inc.., a Delaware corporation (“Exascale”).", "location": "FORM 8-K, Item 1.01. Entry Into a Material Definitive Agreement", "relevance_score": 5}, {"quote": "Merger Sub shall be merged with and into the Company", "location": "EX-2.1, Section 3.1 The Merger", "relevance_score": 5}], "consideration_type": [{"quote": "As consideration for the Merger, the Company Equityholders collectively shall be entitled to receive from Purchaser Surviving Corporation, in the aggregate, a number of Purchaser Surviving Corporation Shares, each valued at $10.00 per share, with an aggregate value equal to Five Hundred Million U.S. Dollars ($500,000,000) (“Merger Consideration”).", "location": "EX-2.1, Section 4.1 Merger Consideration", "relevance_score": 5}, {"quote": "Each issued and outstanding share of Company Class A Common Stock held by a Company Shareholder shall be cancelled and converted into the right to receive a number of Purchaser Class A Shares equal to the quotient obtained by dividing (a) the Per Share Merger Consideration by (b) Ten Dollars ($10.00), with each such Purchaser Class A Share having one (1) vote per share;", "location": "EX-2.1, Section 4.2(a)(ii) Conversion of Company Shares and SAFEs", "relevance_score": 5}, {"quote": "each Company Share issued and outstanding immediately prior to the Effective Time (other than (i) any Company Shares held in the treasury of the Company, which treasury shares shall be canceled as part of the Merger and shall not constitute “Company Shares” hereunder, and (ii) any Company Dissenting Shares) shall be canceled and converted as follows:", "location": "EX-2.1, Section 4.2(a) Conversion of Company Shares and SAFEs", "relevance_score": 5}], "cash_consideration": [], "stock_exchange_ratio": [{"quote": "Each issued and outstanding share of Company Class A Common Stock held by a Company Shareholder shall be cancelled and converted into the right to receive a number of Purchaser Class A Shares equal to the quotient obtained by dividing (a) the Per Share Merger Consideration by (b) Ten Dollars ($10.00), with each such Purchaser Class A Share having one (1) vote per share;", "location": "EX-2.1, Section 4.2(a)(ii) Conversion of Company Shares and SAFEs", "relevance_score": 5}, {"quote": "“Per Share Merger Consideration” means the quotient equal to the Merger Consideration divided by the Fully Diluted Company Capitalization.", "location": "EX-2.1, Article I Definitions", "relevance_score": 5}, {"quote": "“Fully Diluted Company Capitalization” means, without duplication, the aggregate number of Company Shares (a) outstanding immediately prior to the Effective Time and (b) issuable upon the exercise of the SAFEs.", "location": "EX-2.1, Article I Definitions", "relevance_score": 5}, {"quote": "As consideration for the Merger, the Company Equityholders collectively shall be entitled to receive from Purchaser Surviving Corporation, in the aggregate, a number of Purchaser Surviving Corporation Shares, each valued at $10.00 per share, with an aggregate value equal to Five Hundred Million U.S. Dollars ($500,000,000) (“Merger Consideration”).", "location": "EX-2.1, Section 4.1 Merger Consideration", "relevance_score": 5}, {"quote": "“Purchaser Class A Shares” means the Class A shares of common stock, par value $0.0001 per share, of Purchaser Surviving Corporation, with each such share having one (1) vote per share.", "location": "EX-2.1, Article I Definitions", "relevance_score": 5}, {"quote": "No certificates representing fractional Purchaser Surviving Corporation Shares will be issued pursuant to the Merger, and instead any such fractional share that would otherwise be issued will be rounded to the nearest whole share, with a Company Equityholder’s portion of the Merger Consideration that would result in a fractional share of 0.50 or greater rounding up and a Company Equityholder’s portion of the Merger Consideration that would result in a fractional share of less than 0.50 rounding down.", "location": "EX-2.1, Section 4.5(a) Issuance of the Merger Consideration", "relevance_score": 5}], "shareholder_vote_date": [], "closing_conditions": [{"quote": "The respective obligations of each Party to effect the Merger shall be subject to the satisfaction (or waiver, if permissible under applicable Law) on or prior to the Closing Date of the following conditions:", "location": "EX-2.1, Section 11.1 Conditions to Each Party’s Obligation to Effect the Merger", "relevance_score": 5}, {"quote": "(a) There shall not be any Order or Law in effect that restrains, enjoins, prevents, prohibits or make illegal the consummation of the Merger;
(b) The Reincorporation, the Merger and each of the Parent Proposals (other than Parent Proposals described in Section 10.3(e)(vi) – (vii)) have been approved by Parent Required Vote in accordance with the provisions of Parent’s Organizational Documents and the Laws of the British Virgin Islands;
(c) The Purchaser Surviving Corporation’s initial listing application in connection with the Transactions shall have been approved by Nasdaq so that immediately following the Merger, Purchaser Surviving Corporation’s satisfies any applicable initial and continuing listing requirements of Nasdaq;
(d) All consents, approvals and actions of, filings with and notices to any Governmental Authority required to consummate the Transactions shall have been made or obtained;
(e) The Offer shall have been completed in accordance with the terms hereof and the Proxy Statement; and
(f) The Purchaser shall have, as of the Closing Date, an aggregate amount not less than $5,000,000 in any combination of cash, cash in the Trust Account, a private investment in public equity, an equity line of credit, or third-party financing, net of any outstanding checks, wire transfers, or similar items not yet cleared, and net of any cash distributions or transfers made in connection with or as a result of the Transactions contemplated by this Agreement.", "location": "EX-2.1, Section 11.1 Conditions to Each Party’s Obligation to Effect the Merger", "relevance_score": 5}, {"quote": "The obligations of Parent, Purchaser and Merger Sub to effect the Reincorporation and the Merger are further subject to the satisfaction (or waiver, if permissible under applicable Law) on or prior to the Closing Date of the following conditions:", "location": "EX-2.1, Section 11.2 Conditions to Obligations of Parent, Purchaser and Merger Sub", "relevance_score": 5}, {"quote": "(a) The representations and warranties of the Company set forth in Article V shall be true and correct as of the date hereof and as of the Closing, except (i) for representations and warranties that speak as of a specific date or time (which need be true and correct only as of such date or time) and (ii) for breaches of the representations and warranties of the Company set forth in ARTICLE V that would not, individually or in the aggregate, have a Company Material Adverse Effect;
(b) The Company shall have performed in all material respects all obligations required to be performed by it under this Agreement at or prior to the Closing Date;
(c) Since the date of this Agreement, there shall not be any event that is continuing that would individually, or in the aggregate, reasonably be expected to have a Company Material Adverse Effect;", "location": "EX-2.1, Section 11.2 Conditions to Obligations of Parent, Purchaser and Merger Sub", "relevance_score": 5}, {"quote": "(d) Parent shall have received a certificate or letter, signed by the CEO of the Company, certifying or confirming as to the matters set forth in Section 11.2(a), Section 11.2(b) and Section 11.2(c);
(e) The Company shall have executed and delivered to Parent a copy of each Transaction Document to which it is a party;
(f) The Company Shareholders shall have executed and delivered to Parent the Lock-Up Agreement;
(g) Parent shall have received a certificate or confirmation letter, signed by a director or officer of the Company and each of the Company’s Subsidiaries certifying or confirming that true, latest and correct copies of the Organizational Documents of the Company and each of the Company’s Subsidiaries, as in effect on the Closing Date, are attached to such certificate or confirmation letter;
(h) Parent shall have received copies of third party consents (if applicable) set forth on Schedule 11.2(h) in form and substance reasonably satisfactory to Parent, and no such consents have been revoked;", "location": "EX-2.1, Section 11.2 Conditions to Obligations of Parent, Purchaser and Merger Sub", "relevance_score": 5}, {"quote": "(i) Parent shall have received a certificate or letter, signed by a director or officer of the Company, certifying or confirming that true, complete and correct copies of (i) the resolutions of the directors of the Company and (ii) by the directors of the Company authorizing the execution and delivery of this Agreement and the other Transaction Documents to which it is a party and performance by the Company, as applicable, of the Transactions, including the Merger, having been duly and validly adopted and being in full force and effect as of the Closing Date, are attached to such certificate or letter; and
(j) The Company shall have delivered to Parent good standing certificates (or similar documents applicable for such jurisdictions) for the Company certified as of a date no earlier than five (5) days prior to the Closing Date from the Delaware Secretary of State and from each other jurisdiction in which the Company is qualified to do business as a foreign corporation or other entity as of the Closing, in each case provided that good standing certificates or similar documents for the Company are generally available in such jurisdictions.", "location": "EX-2.1, Section 11.2 Conditions to Obligations of Parent, Purchaser and Merger Sub", "relevance_score": 5}, {"quote": "(k) Parent shall have received an acknowledgement duly executed by each Company Safeholder that such Company Safeholder is receiving Purchaser Class A Shares, in a form reasonably acceptable to Parent.", "location": "EX-2.1, Section 11.2 Conditions to Obligations of Parent, Purchaser and Merger Sub", "relevance_score": 5}, {"quote": "The obligation of the Company and the Company Equityholders to effect the Merger is further subject to the satisfaction (or waiver, if permissible under applicable Law) on or prior to the Closing Date of the following conditions:", "location": "EX-2.1, Section 11.3 Conditions to Obligation of the Company", "relevance_score": 5}, {"quote": "(a) The representations and warranties of Parent, Purchaser and Merger Sub set forth in ARTICLE VI shall be true and correct in all material respects, on and as of the Closing Date, as though made on and as of the Closing Date, except (i) to the extent of changes or developments contemplated by the terms of this Agreement and (ii) for such representations and warranties that speak as of a specific date or time (which need be true and correct only as of such date or time);
(b) Parent, Purchaser and Merger Sub shall have performed in all material respects all obligations required to be performed by them under this Agreement at or prior to the Closing Date;
(c) Since the date of this Agreement, there shall not be any event that is continuing that would individually, or in the aggregate, reasonably be expected to have a Parent Material Adverse Effect;", "location": "EX-2.1, Section 11.3 Conditions to Obligation of the Company", "relevance_score": 5}, {"quote": "(d) The Company shall have received a certificate or letter, signed by the CEO or CFO of Parent, certifying as to the matters set forth in Section 11.3(a), Section 11.3(b) and Section 11.3(c) above.
(e) Parent shall have executed and delivered to the Company copy of each Transaction Document to which it is a party;", "location": "EX-2.1, Section 11.3 Conditions to Obligation of the Company", "relevance_score": 5}, {"quote": "(f) Parent shall have delivered to the Company a certificate, signed by an officer of Parent, certifying true, complete and correct copies of (i) the resolutions duly passed by Parent Required Vote at Parent Shareholders’ Meeting and by Purchaser, as the sole shareholder of Merger Sub, approving the Merger and the consummation of the Transactions contemplated by this Agreement and the other Transaction Documents; (ii) certified copies of the resolutions duly passed by Parent’s board of directors, Purchaser and Merger Sub authorizing the execution, delivery and performance of this Agreement and the other Transaction Documents to which each is a party and the performance by Parent, Purchaser and Merger Sub of the Transactions, including the Merger, each having been duly and validly passed and being in full force and effect as of the Closing Date; and (iii) written resignations, in forms satisfactory to the Company, dated as of the Closing Date and effective as of the Closing, executed by such officer(s) and such person(s) serving as director(s) of Parent immediately prior to the Closing;
(g) Parent shall have delivered to the Company a certificate or letter, signed by an officer of Parent, certifying that true, complete and correct copies of the Organizational Documents of Parent, Purchaser and Merger Sub, as in effect on the Closing Date, are attached to such certificate or letter;", "location": "EX-2.1, Section 11.3 Conditions to Obligation of the Company", "relevance_score": 5}, {"quote": "(h) Parent shall have delivered to the Company certificates of good standing with respect to Parent, Purchaser and Merger Sub from their respective applicable jurisdictions of incorporation; and
(i) Except for Parent Shares to be issued pursuant to this Agreement, from the date of this Agreement through the Closing, no Parent Shares shall have been issued to any Person in an amount or on terms other than those approved with the prior written consent of the Company.", "location": "EX-2.1, Section 11.3 Conditions to Obligation of the Company", "relevance_score": 5}], "event_status": [{"quote": "New
York, New York, January 12, 2026 – Exascale Labs Inc. (“Exascale” or the “Company”), a
next-generation AI compute infrastructure platform, and D. Boral ARC Acquisition I Corp. (“BCAR”), a special purpose
acquisition company, today announced that they have entered into a definitive business combination agreement.", "location": "EX-99.1, press release", "relevance_score": 5}, {"quote": "The
proposed business combination has been approved by the boards of directors of Exascale and BCAR, and its closing is expected to
be in the second quarter of 2026, subject to shareholders’ approval and the satisfaction of customary closing conditions.", "location": "EX-99.1, Transaction Details", "relevance_score": 5}], "security_description": [{"quote": "“Company Class A Common Stock” means the Class A common stock of the Company, par value $0.01 per share, with each such share having one (1) vote per share.", "location": "EX-2.1, Article I Definitions", "relevance_score": 5}, {"quote": "each Company Share issued and outstanding immediately prior to the Effective Time (other than (i) any Company Shares held in the treasury of the Company, which treasury shares shall be canceled as part of the Merger and shall not constitute “Company Shares” hereunder, and (ii) any Company Dissenting Shares) shall be canceled and converted as follows:", "location": "EX-2.1, Section 4.2(a) Conversion of Company Shares and SAFEs", "relevance_score": 5}, {"quote": "Each issued and outstanding share of Company Class A Common Stock held by a Company Shareholder shall be cancelled and converted into the right to receive a number of Purchaser Class A Shares", "location": "EX-2.1, Section 4.2(a)(ii) Conversion of Company Shares and SAFEs", "relevance_score": 5}], "effective_date": [{"quote": "Subject to the provisions of this Agreement, at the Closing, after the Reincorporation, Merger Sub or the Company shall file a certificate of merger with the DE SOS. The effective time of the Merger shall be the date that the certificate of merger has been filed with the DE SOS (the time at which the Merger becomes effective is herein referred to as the “Effective Time”).", "location": "EX-2.1, Section 3.3 Effective Time", "relevance_score": 5}], "available_options": [{"quote": "At the Effective Time, by virtue of the Merger and without any action on the part of any holder of Company Shares, each Company Share issued and outstanding immediately prior to the Effective Time (other than (i) any Company Shares held in the treasury of the Company, which treasury shares shall be canceled as part of the Merger and shall not constitute “Company Shares” hereunder, and (ii) any Company Dissenting Shares) shall be canceled and converted as follows:", "location": "EX-2.1, Section 4.2(a) Conversion of Company Shares and SAFEs", "relevance_score": 5}, {"quote": "Each issued and outstanding share of Company Class A Common Stock held by a Company Shareholder shall be cancelled and converted into the right to receive a number of Purchaser Class A Shares equal to the quotient obtained by dividing (a) the Per Share Merger Consideration by (b) Ten Dollars ($10.00)", "location": "EX-2.1, Section 4.2(a)(ii) Conversion of Company Shares and SAFEs", "relevance_score": 5}], "default_option": [], "election_deadline": []}

