{"acquirer": [{"quote": "SL Science Holding Limited, a Cayman Islands exempted company limited by shares (“PubCo”), HSPT, CW Mega Limited, a Cayman Islands exempted company limited by shares and a wholly-owned subsidiary of PubCo (“Merger Sub I”)", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}, {"quote": "Merger Sub I will merge with and into HSPT, with HSPT as the surviving entity and a wholly-owned subsidiary of PubCo", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}], "target": [{"quote": "Horizon Space Acquisition II Corp., a Cayman Islands exempted company limited by shares (“HSPT”)", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}, {"quote": "Merger Sub I will merge with and into HSPT, with HSPT as the surviving entity and a wholly-owned subsidiary of PubCo", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}], "consideration_type": [{"quote": "each Acquiror Ordinary Share (which, for the avoidance of doubt, includes the Acquiror Ordinary Shares held as a result of the Unit Separation and the Acquiror Right Conversion) issued and outstanding immediately prior to the First Merger Effective Time will automatically be cancelled and cease to exist in exchange for the right to receive one (1) newly issued PubCo Ordinary Share.", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}, {"quote": "In connection with the completion of the Business Combination, each public shareholder may elect to redeem all or a portion of its public shares for a per-share price, payable in cash", "location": "DEFM14A | Extraordinary General Meeting of HSPT Shareholders — Redemption Rights, page 84", "relevance_score": 5}, {"quote": "Each Redeeming Acquiror Share issued and outstanding immediately prior to the First Merger Effective Time shall automatically be cancelled and cease to exist and shall thereafter represent only the right to be paid Acquiror Redemption Price per share in accordance with the Acquiror Charter.", "location": "DEFM14A | Annex A — Business Combination Agreement, Section 3.1(a)(v), page A-16", "relevance_score": 5}], "cash_consideration": [{"quote": "“Acquiror Redemption Price” means a per-share price, payable in cash, equal to the aggregate amount then on deposit in the Trust Account calculated as of two business days prior to the First Closing, or such other time as agreed by Acquiror and the Company in writing including interest earned on the Trust Account (such interest shall be net of taxes payable) and not previously released to the Acquiror to pay its taxes, divided by the number of then issued Acquiror Public Shares, in connection with obtaining Acquiror Shareholder Approval.", "location": "DEFM14A | Annex A — Business Combination Agreement, Section 1.1, page A-4", "relevance_score": 5}, {"quote": "For illustrative purposes, as of December 29, 2025 (the “Record Date”), the redemption price was approximately $10.53 per share less any owed but unpaid taxes on the funds in the Trust Account.", "location": "DEFM14A | Letter to HSPT shareholders", "relevance_score": 5}, {"quote": "Each Redeeming Acquiror Share issued and outstanding immediately prior to the First Merger Effective Time shall automatically be cancelled and cease to exist and shall thereafter represent only the right to be paid Acquiror Redemption Price per share in accordance with the Acquiror Charter.", "location": "DEFM14A | Annex A — Business Combination Agreement, Section 3.1(a)(v), page A-16", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "each Acquiror Ordinary Share (which, for the avoidance of doubt, includes the Acquiror Ordinary Shares held as a result of the Unit Separation and the Acquiror Right Conversion) issued and outstanding immediately prior to the First Merger Effective Time will automatically be cancelled and cease to exist in exchange for the right to receive one (1) newly issued PubCo Ordinary Share.", "location": "DEFM14A | Proxy Statement, opening business-combination description", "relevance_score": 5}, {"quote": "Each Acquiror Right issued and outstanding immediately prior to the First Merger Effective Time shall be automatically converted into one-tenth (1/10) Acquiror Ordinary Share (the “Acquiror Right Conversion”); provided that no Acquiror Ordinary Share will be issued in connection with the Acquiror Right Conversion such that if a holder of Acquiror Rights would be entitled to receive a fractional Acquiror Ordinary Share upon the Acquiror Right Conversion, the number of Acquiror Ordinary Share to be issued to such holder upon the Acquiror Right Conversion shall be rounded down to the nearest whole number of Acquiror Ordinary Shares.", "location": "DEFM14A | Annex A — Business Combination Agreement, Section 3.1(a)(ii), page A-15", "relevance_score": 5}, {"quote": "each Acquiror Ordinary Share (which, for the avoidance of doubt, includes the Acquiror Ordinary Shares held as a result of the Unit Separation and Acquiror Right Conversion) issued and outstanding immediately prior to the First Merger Effective Time (other than (1) any Acquiror Ordinary Shares referred to in Section 3.1(a)(iv), (2) Redeeming Acquiror Shares and (3) Dissenting Acquiror Shares) shall automatically be cancelled and cease to exist in exchange for the right to receive one newly issued PubCo Ordinary Share.", "location": "DEFM14A | Annex A — Business Combination Agreement, Section 3.1(a)(iii), pages A-15–A-16", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "The Extraordinary Meeting of HSPT shall be held on February 3, 2026, at 9:00 am, Eastern Time, at the offices of Robinson & Cole LLP located at 666 Third Avenue, 20th Floor, New York, NY 10017, and virtually via teleconference using the dial-in information: +1 813-308-9980 (Access Code: 173547), or at such other time, on such other date and at such other place to which the meeting may be postponed or adjourned.", "location": "DEFM14A | Extraordinary General Meeting of HSPT Shareholders — Date, Time and Place, page 82", "relevance_score": 5}, {"quote": "At the Extraordinary Meeting, HSPT is asking holders of HSPT Ordinary Shares to:
• consider and vote upon the Business Combination Proposals;", "location": "DEFM14A | Extraordinary General Meeting of HSPT Shareholders — Purpose of HSPT Extraordinary Meeting, page 82", "relevance_score": 5}], "closing_conditions": [{"quote": "The obligations of each Party to consummate, or cause to be consummated, the Mergers, are subject to the satisfaction of the following conditions, any one or more of which may be waived in writing by the party or parties whose obligations are conditioned thereupon:
(a) the Acquiror Shareholder Approval shall have been obtained and remain in full force and effect;
(b) the Company Shareholder Approval shall have been obtained and remain in full force and effect;
(c) the Proxy/Registration Statement shall have become effective under the Securities Act and no stop order suspending the effectiveness of the Proxy/Registration Statement shall have been issued and no proceedings for that purpose shall have been initiated or threatened by the SEC and not withdrawn;
(d) the PubCo Ordinary Shares to be issued in connection with the Transactions shall have been approved for listing on Nasdaq, subject to official notice of issuance;
(e) all Regulatory Approvals necessary to consummate the Transactions as contemplated hereby shall have been obtained;
(f) no Governmental Authority shall have enacted, issued, promulgated, enforced or entered any Law (whether temporary, preliminary or permanent) or Governmental Order that is then in effect and which has the effect of making the First Closing or the Second Closing illegal or which otherwise prevents or prohibits consummation of the First Closing or the Second Closing (any of the foregoing, a “restraint”), other than any such restraint that is immaterial;
