{"acquirer": [{"quote": "Vine Hill will merge with and into SPAC Merger Sub, with SPAC Merger Sub being the surviving entity as a direct, wholly-owned subsidiary of Holdco", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Structure of the Business Combination, page 103", "relevance_score": 5}, {"quote": "“Holdco” means Odysseus Holdings Limited, a private company limited by shares organized under the laws of Jersey.", "location": "PREM14A, Frequently Used Terms, page vii", "relevance_score": 5}, {"quote": "“SPAC Merger Sub” means Odysseus (Cayman) Limited, a Cayman Islands exempted company and a wholly owned subsidiary of Holdco.", "location": "PREM14A, Frequently Used Terms, page viii", "relevance_score": 5}], "target": [{"quote": "“Vine Hill” means Vine Hill Capital Investment Corp., a Cayman Islands exempted company.", "location": "PREM14A, Frequently Used Terms, page viii", "relevance_score": 5}, {"quote": "Vine Hill will merge with and into SPAC Merger Sub, with SPAC Merger Sub being the surviving entity as a direct, wholly-owned subsidiary of Holdco", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Structure of the Business Combination, page 103", "relevance_score": 5}], "consideration_type": [{"quote": "As consideration for the SPAC Merger, at the effective time of the SPAC Merger, (a) each issued and outstanding Vine Hill Class A Share (including each Vine Hill Class A Share issued upon the Sponsor Share Conversion (as defined below)) will be converted into one Holdco Ordinary Share and (b) each outstanding public warrant of Vine Hill (each, a “Vine Hill Public Warrant”) will be assumed by Holdco as a public warrant of Holdco (each, a “Holdco Warrant”), having substantially the same terms and conditions and exercisable for Holdco Ordinary Shares.", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Business Combination Consideration, page 103", "relevance_score": 5}, {"quote": "Vine Hill Public Shareholders may elect to redeem all or a portion of the Vine Hill Public Shares held by them, regardless of if or how they vote in respect of the Business Combination Proposal.", "location": "PREM14A, Extraordinary General Meeting of Vine Hill Shareholders — Redemption Rights, page 100", "relevance_score": 5}], "cash_consideration": [{"quote": "If the Business Combination is consummated and if a Vine Hill Public Shareholder properly exercises its right to redeem all or a portion of the Vine Hill Public Shares that it holds and timely delivers its share certificates (if any) and other redemption forms (as applicable) to the Transfer Agent, Vine Hill will redeem such Vine Hill Public Shares for a per-share price, payable in cash, equal to the pro rata portion of the aggregate amount then on deposit in the Trust Account, calculated as of two business days prior to the Closing, including interest earned on the Trust Account and not previously released to Vine Hill (net of taxes payable, if any) (such redemption price being referred to herein as the “Redemption Price”).", "location": "PREM14A, Notice of Extraordinary General Meeting — Redemption Rights", "relevance_score": 5}, {"quote": "For illustrative purposes, based on the Trust Account balance as of the Record Date, this would have amounted to approximately $10.68 per Vine Hill Public Share.", "location": "PREM14A, Notice of Extraordinary General Meeting — Redemption Rights", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "As consideration for the SPAC Merger, at the effective time of the SPAC Merger, (a) each issued and outstanding Vine Hill Class A Share (including each Vine Hill Class A Share issued upon the Sponsor Share Conversion (as defined below)) will be converted into one Holdco Ordinary Share and (b) each outstanding public warrant of Vine Hill (each, a “Vine Hill Public Warrant”) will be assumed by Holdco as a public warrant of Holdco (each, a “Holdco Warrant”), having substantially the same terms and conditions and exercisable for Holdco Ordinary Shares.", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Business Combination Consideration, page 103", "relevance_score": 5}, {"quote": "“Holdco Ordinary Shares” means the no par value ordinary shares of Holdco.", "location": "PREM14A, Frequently Used Terms, page vii", "relevance_score": 5}, {"quote": "“Vine Hill Class A Shares” means the Class A ordinary shares, par value $0.0001 per share, of Vine Hill.", "location": "PREM14A, Frequently Used Terms, page viii", "relevance_score": 5}, {"quote": "The number of Holdco Ordinary Shares that each holder of SPAC Shares is entitled to receive as a result of the SPAC Merger and as otherwise contemplated by this Agreement shall be adjusted to reflect appropriately the effect of any share split, share subdivision, split-up, reverse share split, share consolidation, share dividend or distribution (including any dividend or distribution of securities convertible into Holdco Ordinary Shares), extraordinary cash dividend, reorganization, recapitalization, reclassification, combination, exchange of shares or other like change with respect to Holdco Ordinary Shares occurring on or after the date hereof and prior to the Closing, if any.", "location": "PREM14A, Annex A — Business Combination Agreement, Section 3.01(e), page A-16", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "The Extraordinary General Meeting will be held on March 27, 2026 at 10:00 a.m., Eastern Time.", "location": "PREM14A, Extraordinary General Meeting of Vine Hill Shareholders — Date, Time and Place, page 96", "relevance_score": 5}, {"quote": "At the Extraordinary General Meeting, Vine Hill is asking holders of Vine Hill Ordinary Shares to consider and vote upon:
• the Business Combination Proposal. A current copy of the Business Combination Agreement is attached to this proxy statement/prospectus as Annex A;
• the SPAC Merger Proposal;", "location": "PREM14A, Extraordinary General Meeting of Vine Hill Shareholders — Purpose of the Extraordinary General Meeting, page 96", "relevance_score": 5}], "closing_conditions": [{"quote": "Under the Business Combination Agreement, the obligations of the parties to consummate (or cause to be consummated) the Business Combination are subject to the satisfaction of or waiver by all parties to the Business Combination Agreement (to the extent permitted by applicable law) of, a number of customary conditions, including, among other things: (i) approval by Vine Hill’s shareholders of the Condition Precedent Proposals; (ii) approval by CoinShares Shareholders of the Scheme of Arrangement; (iii) receipt of certain specified regulatory approvals, including, without limitation, expiration or termination of any waiting period under the Hart-Scott-Rodino Act; (iv) consummation of the Business Combination not being prohibited or enjoined by any order, rule, regulation or other applicable law; (v) absence of any secured creditors of Vine Hill; (vi) Holdco Ordinary Shares having been approved for listing on Nasdaq (or any other public stock market or exchange in the United States as may be agreed by CoinShares and Vine Hill), subject to official notice of issuance thereof; (vii) effectiveness of the registration statement of which this proxy statement/prospectus forms a part in accordance with the Securities Act and absence of any stop order issued by the SEC which remains in effect with respect to the registration statement of which this proxy statement/prospectus forms a part; and (viii) the Royal Court of Jersey sanctioning the Scheme of Arrangement and the submission by CoinShares of the court’s order to the Registrar of Companies of Jersey for registration.", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Closing Conditions, page 105", "relevance_score": 5}, {"quote": "“Condition Precedent Proposals” mean the Business Combination Proposal, the SPAC Merger Proposal and the Organizational Document Proposal.", "location": "PREM14A, Frequently Used Terms, page vi", "relevance_score": 5}, {"quote": "The obligations of Vine Hill to consummate the Business Combination are also subject to, the satisfaction or waiver by Vine Hill of a number of conditions, including, among other things: (i) the respective representations and warranties of CoinShares, Holdco and SPAC Merger Sub being true and correct, subject to the applicable materiality standards contained in the Business Combination Agreement; (ii) material performance or compliance by CoinShares, Holdco and SPAC Merger Sub with their respective pre-Closing covenants; (iii) no CoinShares Material Adverse Effect having occurred since the date of the Business Combination Agreement that is continuing; and (iv) material performance by CoinShares and the Key CoinShares Shareholders (as defined below) with their respective pre-Closing covenants under the Shareholder Support Agreement (as defined below).", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Closing Conditions, page 105", "relevance_score": 5}, {"quote": "The obligations of CoinShares, Holdco and SPAC Merger Sub to consummate the Business Combination are also subject to, the satisfaction or waiver by CoinShares of a number of conditions, including among other things: (i) no information having been made public by Vine Hill or otherwise made available to CoinShares, Holdco or SPAC Merger Sub by Vine Hill, being materially inaccurate, incomplete or misleading in any material respect and Vine Hill having made public all material information which is required to be made public under applicable law; (ii) no state of facts, changes, circumstances, occurrences, events or effects having occurred that has had or would reasonably be expected to have, a materially adverse effect on (a) the business, assets, financial condition or results of operations of Vine Hill or (b) the ability of Vine Hill to perform its material obligations under the Business Combination Agreement or to consummate the Business Combination, in each case, subject to certain exceptions; (iii) none of Vine Hill or the Sponsor having (x) taken any action that is likely to impair the prerequisites for the Closing or (y) failed to take any action the failure of which is likely to impair the prerequisites for the Closing; and (iv) completion of the Vine Hill Private Warrant Cancellation.", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Closing Conditions, page 105", "relevance_score": 5}, {"quote": "The representations and warranties of SPAC contained in Section 5.07(a) are true and correct in all material respects on and as of the Closing Date; and all other representations and warranties set forth in Article V hereof are true and correct (without giving effect to any limitation as to “materiality” or “SPAC Material Adverse Effect” or any similar limitation contained herein) on and as of the Closing Date as though made on and as of the Closing Date (except to the extent that any such representation and warranty expressly speaks as of an earlier date, in which case such representation and warranty shall be true and correct as of such earlier date), except where any failures of such representations and warranties to be so true and correct, individually or in the aggregate, has not had and would not reasonably be expected to have a SPAC Material Adverse Effect.", "location": "PREM14A, Annex A — Business Combination Agreement, Section 3.07(d)(i), page A-20", "relevance_score": 3}, {"quote": "SPAC has performed or complied with all agreements and covenants required by this Agreement to be performed or complied with by it on or prior to the Closing Date, in each case in all material respects.", "location": "PREM14A, Annex A — Business Combination Agreement, Section 3.07(d)(ii), page A-20", "relevance_score": 3}], "event_status": [{"quote": "On September 8, 2025, Vine Hill, Holdco, SPAC Merger Sub and CoinShares entered into the Business Combination Agreement.", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Structure of the Business Combination, page 103", "relevance_score": 5}, {"quote": "Vine Hill is holding the Extraordinary General Meeting to, among other things, obtain the approvals required for the Business Combination and the other transactions contemplated by the Business Combination Agreement.", "location": "PREM14A, Questions and Answers for Vine Hill Shareholders, page xiii", "relevance_score": 5}], "security_description": [{"quote": "“Vine Hill Class A Shares” means the Class A ordinary shares, par value $0.0001 per share, of Vine Hill.", "location": "PREM14A, Frequently Used Terms, page viii", "relevance_score": 5}, {"quote": "each issued and outstanding Vine Hill Class A Share (including each Vine Hill Class A Share issued upon the Sponsor Share Conversion (as defined below)) will be converted into one Holdco Ordinary Share", "location": "PREM14A, The Business Combination Proposal — Business Combination Agreement — Business Combination Consideration, page 103", "relevance_score": 5}, {"quote": "each SPAC Class A Share (after taking into account the SPAC Class B Share Conversion and the SPAC Unit Separation, but not including the Sponsor Forfeited Shares, the SPAC Dissenting Shares, the SPAC Shares cancelled pursuant to Section 3.01(f) or the SPAC Redeeming Share), issued and outstanding immediately prior to the SPAC Effective Time shall be converted into one (1) validly issued, fully paid and non-assessable Holdco Ordinary Share", "location": "PREM14A, Annex A — Business Combination Agreement, Section 3.01(e), page A-16", "relevance_score": 5}, {"quote": "each Public Warrant that is outstanding and unexercised immediately prior to the SPAC Effective Time (assuming consummation of the SPAC Unit Separation), shall be converted into and become a warrant to purchase one (1) Holdco Ordinary Share", "location": "PREM14A, Annex A — Business Combination Agreement, Section 3.01(i), page A-17", "relevance_score": 5}], "effective_date": [{"quote": "The SPAC Merger will become effective at such time as the SPAC Plan of Merger is duly registered by the Cayman Registrar or at such later date or time as is agreed between the Company and SPAC and specified in the SPAC Plan of Merger pursuant to the Cayman Companies Act", "location": "PREM14A, Annex A — Business Combination Agreement, Section 2.04(b), page A-15", "relevance_score": 5}, {"quote": "The Parties shall take all necessary actions such that the Acquisition Effective Time shall take place at least one (1) day after the SPAC Effective Time and, in any event, on the Closing Date.", "location": "PREM14A, Annex A — Business Combination Agreement, Section 2.04(c), page A-15", "relevance_score": 5}], "available_options": [{"quote": "Vine Hill Public Shareholders may elect to redeem all or a portion of the Vine Hill Public Shares held by them, regardless of if or how they vote in respect of the Business Combination Proposal.", "location": "PREM14A, Extraordinary General Meeting of Vine Hill Shareholders — Redemption Rights, page 100", "relevance_score": 5}, {"quote": "if the Business Combination is consummated, Vine Hill will redeem the Vine Hill Public Shares for a pro rata portion of funds deposited in the Trust Account, calculated as of two business days prior to the Closing.", "location": "PREM14A, Questions and Answers for Vine Hill Shareholders — How do I exercise my redemption rights?, page xviii", "relevance_score": 5}, {"quote": "If you are a Vine Hill Public Shareholder and wish to exercise your right to redeem your Vine Hill Public Shares, you must:
