{"acquirer": [{"quote": "the Agreement and Plan of Merger, dated as of January 20, 2026 (as it may be amended from time to time, the “Merger Agreement”), by and among Smithfield Foods, Inc., a Virginia corporation (“Parent”), Boardwalk Merger Sub Inc., a Delaware corporation and wholly-owned subsidiary of Parent (“Merger Sub”), and the Company, providing for, among other things, the merger of Merger Sub with and into the Company (the “Merger”), with the Company surviving the Merger as a wholly-owned subsidiary of Parent", "location": "PREM14A, introductory letter", "relevance_score": 5}], "target": [{"quote": "A special meeting of stockholders of NATHAN’S FAMOUS, INC., a Delaware corporation (the “Company,” “Nathan’s,” “we,” “us” or “our”), will be held on [•], 2026, at [•], Eastern Time (the “Special Meeting”).", "location": "PREM14A, introductory letter", "relevance_score": 5}, {"quote": "Merger Sub will merge with and into the Company, with the Company surviving the Merger as a wholly-owned subsidiary of Parent", "location": "PREM14A, introductory letter", "relevance_score": 5}], "consideration_type": [{"quote": "At the Effective Time, each outstanding share of Common Stock (other than (i) shares owned or held in treasury by the Company or owned by Parent, Merger Sub or any of their respective affiliates (collectively,", "location": "PREM14A, Summary — Merger Consideration, pages 4–5", "relevance_score": 3}, {"quote": "“Cancelled Shares”) and (ii) shares held by stockholders who are entitled to and have properly demanded appraisal for such shares in accordance with Section 262 of the DGCL (“Dissenting Shares”)) will be converted automatically into the right to receive $102.00 per share in cash, without interest and less any applicable withholding tax (the “Merger Consideration”).", "location": "PREM14A, Summary — Merger Consideration, page 5", "relevance_score": 5}], "cash_consideration": [{"quote": "“Cancelled Shares”) and (ii) shares held by stockholders who are entitled to and have properly demanded appraisal for such shares in accordance with Section 262 of the DGCL (“Dissenting Shares”)) will be converted automatically into the right to receive $102.00 per share in cash, without interest and less any applicable withholding tax (the “Merger Consideration”).", "location": "PREM14A, Summary — Merger Consideration, page 5", "relevance_score": 5}, {"quote": "each share of Company Common Stock owned or held in treasury by the Company and any shares of Company Common Stock owned by Parent or Merger Sub (or any of their respective Affiliates) immediately prior to the Effective Time shall automatically be canceled and shall cease to exist and no consideration shall be delivered in exchange therefor;", "location": "PREM14A, Annex A — Merger Agreement, Section 2.03(b), page A-14", "relevance_score": 5}, {"quote": "shares of Company Common Stock issued and outstanding immediately prior to the Effective Time and held by a holder who has not voted in favor of the adoption of this Agreement or consented thereto in writing, who is entitled to appraisal under the DGCL and who has properly exercised appraisal rights for such shares in accordance with Section 262 of the DGCL, shall not be converted into a right to receive the Per Share Merger Consideration but instead shall be entitled only to payment for such shares determined in accordance with Section 262 of the DGCL", "location": "PREM14A, Annex A — Merger Agreement, Section 2.05, page A-16", "relevance_score": 5}, {"quote": "If, during the period between the date hereof and the Effective Time, any change in the outstanding shares of capital stock of the Company shall occur, including by reason of any reclassification, recapitalization, stock split (including reverse stock split) or combination, exchange or readjustment of shares, or any stock dividend, the Per Share Merger Consideration and any other amounts payable pursuant to Article 2 of this Agreement shall be adjusted to equitably provide holders of the Company Common Stock the same economic effect as contemplated by this Agreement prior to such event.", "location": "PREM14A, Annex A — Merger Agreement, Section 2.07, page A-17", "relevance_score": 5}], "stock_exchange_ratio": [{"quote": "each share of Company Common Stock issued and outstanding immediately prior to the Effective Time shall be automatically canceled and converted into the right to receive $102.00 in cash without interest (the “Per Share Merger Consideration”).", "location": "PREM14A, Annex A — Merger Agreement, Section 2.03(a), page A-14", "relevance_score": 5}], "shareholder_vote_date": [{"quote": "A special meeting of stockholders of NATHAN’S FAMOUS, INC., a Delaware corporation (the “Company,” “Nathan’s,” “we,” “us” or “our”), will be held on [•], 2026, at [•], Eastern Time (the “Special Meeting”).", "location": "PREM14A, introductory letter", "relevance_score": 5}], "closing_conditions": [{"quote": "The respective obligations of the Company, Parent and Merger Sub to consummate the Merger are subject to the satisfaction of or, to the extent permitted by Applicable Law, waiver of, at or prior to the Closing, the following conditions:", "location": "PREM14A, Annex A — Merger Agreement, Section 7.01, page A-54", "relevance_score": 5}, {"quote": "(a) the Company Stockholder Approval shall have been obtained;
(b) no Governmental Authority having jurisdiction over any party hereto shall have issued any Order or other action that is in effect (whether temporary, preliminary or permanent) restraining, enjoining or otherwise prohibiting the consummation of the Merger and no Law shall have been adopted that makes consummation of the Merger illegal or otherwise prohibited;", "location": "PREM14A, Annex A — Merger Agreement, Section 7.01, page A-54", "relevance_score": 5}, {"quote": "(c) the applicable waiting period (and any extension thereof, subject to Section 6.09) applicable to the Merger under any applicable Antitrust Law, including the HSR Act, shall have expired or been terminated; and
